import heapq

class Graph:
    def __init__(self):
        self.graph = {}

    def add_edge(self, u, v, weight=1):
        if u not in self.graph:
            self.graph[u] = []
        self.graph[u].append((v, weight))

    def get_neighbors(self, u):
        return self.graph.get(u, [])

    def dijkstra(self, source):
        distances = {u: float('inf') for u in self.graph}
        distances[source] = 0
        priority_queue = [(0, source)]  # (weight, node)
        visited = set()

        while priority_queue:
            current_weight, current_node = heapq.heappop(priority_queue)

            if current_node in visited:
                continue

            visited.add(current_node)

            for neighbor, weight in self.graph.get(current_node, []):
                new_weight = current_weight + weight
                if new_weight < distances[neighbor]:
                    distances[neighbor] = new_weight
                    heapq.heappush(priority_queue, (new_weight, neighbor))

        return distances


def a_star_search(graph, source, target):
    """
    A* Search algorithm implemented without Rabin-Karp.

    Args:
        graph: An instance of the Graph class.
        source: The starting node.
        target: The destination node.

    Returns:
        A list of nodes representing the path from source to target, or None if no path is found.
    """
    distances = graph.dijkstra(source)  # Calculate distances using Dijkstra
    closed_set = set()  
    open_set = [(0, source)]  # (cost, node)

    while open_set:
        cost, current_node = heapq.heappop(open_set)

        if current_node == target:  
            return reconstruct_path(distances, current_node)

        if current_node in closed_set:
            continue

        closed_set.add(current_node)  

        for neighbor, weight in graph.get_neighbors(current_node):
            new_cost = cost + weight 
            if neighbor not in closed_set and new_cost < distances[neighbor]:
                distances[neighbor] = new_cost
                heapq.heappush(open_set, (new_cost, neighbor))

    return None  # No path found

def reconstruct_path(distances, current_node):
    path = []
    while current_node is not None:
        path.append(current_node)
        current_node = distances[current_node]
    return path[::-1]  # Reverse for correct order


# Example usage
graph = Graph()
graph.add_edge(0, 1, 1)
graph.add_edge(0, 2, 4)
graph.add_edge(1, 2, 3)
graph.add_edge(2, 3, 2)
graph.add_edge(1, 3, 5)

source = 0
target = 3
path = a_star_search(graph, source, target)
if path:
    print("Path:", path)
else:
    print
